def lookup(city: str, state: str) -> Optional[Tuple[float, float]]:
    """Return (lat, lng) for a US city/state pair, or None if not found."""
    key = (city.strip().lower(), state.strip().upper())
    if key in CITY_COORDS:
        return CITY_COORDS[key]
    # Try state centroid
    st = state.strip().upper()
    if st in STATE_CENTROIDS:
        return STATE_CENTROIDS[st]
    return None
